class Solution {
    public int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> minHead = new PriorityQueue<>();
        for(int num : nums){
            if(minHead.size() < k){
                minHead.offer(num);
            } else {
                if(minHead.peek()<num){
                    minHead.poll();
                    minHead.offer(num);
                }
            }
        }
        return minHead.peek();
    }
}
